import React from 'react';
import { Link } from 'react-router-dom';

const MainPage = () => {
  return (
    <div className="container text-white text-center mt-5">
      <h1 className="display-3 mb-4">
        SportPulse
      </h1>
      <p className="lead">Футбол в прямом эфире. Без рекламы. Без регистрации.</p>
      <div className="mt-4">
        <Link to="/live" className="btn btn-danger mx-2">🔴 Live</Link>
        <Link to="/upcoming" className="btn btn-warning mx-2">🟡 Предстоящие</Link>
        <Link to="/finished" className="btn btn-secondary mx-2">⚪ Завершённые</Link>
      </div>
    </div>
  );
};

export default MainPage;
